"""Self-contained presentation walkthrough with no datasets or API calls."""
import streamlit as st

from secure_context.tokens import Session, rehydrate


def render_demo():
    st.title("From private client record to useful AI context")
    st.caption("Fictional financial client · Scripted demo")
    st.caption("Advisor task: prepare a meeting brief for Maya Patel. "
               "Turn off Guided demo in the sidebar to explore the interactive benchmark app.")
    if "guided_session" not in st.session_state:
        st.session_state.guided_session = Session()
    session = st.session_state.guided_session
    person = session.token("PERSON", "Maya Patel")
    email = session.token("EMAIL", "maya@example.com")
    steps = ["1. Raw record", "2. Identify PII", "3. Split storage", "4. Tokenize",
             "5. Minimize context", "6. Model boundary", "7. Restore the answer"]
    raw = ("Name: Maya Patel\nEmail: maya@example.com\nAge: 47\nLocation: Boston, MA\n"
           "Occupation: Surgeon\nAssets: $3.2 million\nObjective: Retirement planning\n"
           "Risk tolerance: Moderate\nHorizon: 15 years\nLiquidity: $80,000 within 12 months")
    prompt = (f"Task: Prepare meeting brief.\nClient ref: {person}\nContact ref: {email}\n"
              "Age: 40-49\nAssets: $1M-$5M\nObjective: Retirement planning\n"
              "Risk tolerance: Moderate\nTime horizon: 15 years\n"
              "Liquidity need: $50K-$150K within a year")
    answer = (f"Meeting brief for {person}:\n"
              "1. Review retirement goals and the 15-year horizon.\n"
              "2. Discuss moderate risk tolerance.\n"
              "3. Confirm the upcoming liquidity need; the exact amount was not shared.\n"
              f"Send the agenda to {email}.")
    explanations = [
        "The advisor needs a useful meeting brief. Sending the whole client record would disclose more than that task requires.",
        "Direct identifiers identify a person immediately. Quasi-identifiers, such as age and occupation, can identify them in combination.",
        "Identity and financial context are kept in separate stores. A trusted local service holds the link between their random IDs.",
        "The model can refer to the client consistently using a temporary token. The original value and session key remain local.",
        "Choose the least revealing representation that preserves useful task information, subject to the configured crowd-size constraint.",
        "Only the selected prompt crosses the answer-generation boundary. The model uses it to prepare a meeting brief.",
        "Restore known tokens locally so the advisor sees a readable answer. Unknown or ambiguous tokens are flagged for review.",
    ]
    pipeline, data, models, metrics = st.tabs(["Pipeline demo", "Data", "Tech stack & models", "Evaluation"])
    with pipeline:
        step = st.radio("Walkthrough step", steps, key="guided_step")
        idx = steps.index(step)
        st.progress((idx + 1) / len(steps), text=f"Step {idx + 1} of {len(steps)}")
        walkthrough, technical = st.tabs(["Example", "How it works"])
        with walkthrough:
            st.subheader(steps[idx])
            st.write(explanations[idx])
            left, right = st.columns(2)
            if idx == 0:
                left.code(raw, language=None)
                right.markdown("**Say:** ‘We want the model to understand the task without receiving the entire client identity and financial record.’")
            elif idx == 1:
                left.table({"Direct identifier": ["Maya Patel", "maya@example.com"], "Label": ["PERSON", "EMAIL"]})
                right.table({"Potential linkage attributes": ["Age 47", "Boston", "Surgeon", "$3.2 million"]})
            elif idx == 2:
                left.markdown("**Identity vault, local**\n\nName, email, token mappings and the context-to-identity link.")
                right.markdown("**Context store, local**\n\nFinancial profile, holdings and tokenized notes under a separate random context ID.")
                st.caption("Prototype: separate SQLite stores with application role checks. AES-GCM encrypts selected identifier fields, not the entire vault.")
            elif idx == 3:
                left.code("Maya Patel\nmaya@example.com", language=None)
                right.code(f"{person}\n{email}", language=None)
                st.caption("These tokens are generated by the actual Session implementation, using HMAC-SHA256 and a random session key.")
                if st.button("Rotate demo session key"):
                    st.session_state.guided_session = Session()
                    st.rerun()
            elif idx == 4:
                st.table({"Field": ["Age", "Location", "Occupation", "Assets", "Liquidity", "Objective / risk / horizon"],
                          "Original": ["47", "Boston", "Surgeon", "$3.2M", "$80K within 12 months", "Task-relevant values"],
                          "Illustrative shared view": ["40-49", "Omitted", "Omitted", "$1M-$5M", "$50K-$150K within a year", "Retained"]})
                st.write("Across repeated requests, the exposure ledger combines earlier disclosures with the proposed context before checking the threshold.")
            elif idx == 5:
                left.markdown("**Outgoing prompt**")
                left.code(prompt, language=None)
                right.markdown("**Scripted model answer**")
                right.code(answer, language=None)
            else:
                left.markdown("**Answer with tokens**")
                left.code(answer, language=None)
                right.markdown("**Advisor view, restored locally**")
                restored = rehydrate(answer, session)
                right.code(restored.text, language=None)
                st.success(f"{restored.resolved} tokens restored by the actual rehydrator; {len(restored.unresolved)} unresolved.")
                st.write("Next: turn off Guided demo to compare masking and adaptive policies, inspect cumulative exposure, and review saved baseline results.")
        with technical:
            st.subheader(steps[idx] + ": implementation")
            details = [
                ("Structured input", "The Client record holds identity fields, financial attributes, holdings and advisor notes. A task ID such as meeting_prep selects predefined information requirements.", "data.py: Client; policy.py: TASKS"),
                ("Detection and canonicalization", "Regex finds structured IDs. The CRM dictionary matches known names and contact details. Optional detectors handle unfamiliar text. Detections carry start/end offsets, a label and a canonical value. Rule-based normalization maps recognized aliases to the same canonical identity.", "detect.py: EnsembleDetector, resolve_coreference"),
                ("Separate stores and a private link", "The identity vault and context store use independent random UUIDs. The ctx_link table inside the vault connects them. SQLite role checks control access. AES-256-GCM encrypts SSN, account, routing number and DOB; other identity fields and token mappings are stored inside the vault without field encryption.", "vault.py: IdentityVault, ContextStore, SplitStorage"),
                ("Session-keyed HMAC", "A random 32-byte session key feeds HMAC-SHA256 over LABEL|canonical_value. The prototype uses the first six hex characters in the token and stores a local lookup for restoration. Storage tokens are converted to session tokens before model use. Production hardening includes longer tokens and collision handling.", "tokens.py: Session.token; vault.py: session_notes"),
                ("Policy search with cumulative exposure", "Candidate policies choose exact, generalized or omitted values for each field. choose_policy maximizes a rule-based task utility score subject to cumulative k >= k_min, with larger k breaking ties. The ledger combines the most detailed disclosures across requests. If no policy qualifies, the pipeline skips the model call.", "privacy.py: KEngine, ExposureLedger, choose_policy"),
                ("Prompt construction and hosted inference", "build_prompt renders the selected fields with session tokens. GroqLLM sends the system and user messages to Groq's chat-completions endpoint. Requests use atomic response caches and bounded retries. Structured output is validated locally before caching, with a plain-JSON fallback after repeated provider validation failures.", "tasks.py: build_prompt; llm.py: GroqLLM"),
                ("Local lookup and request trace", "rehydrate substitutes known tokens using the session mapping, without reversing the HMAC. A malformed token is repaired only when one known token matches. The request trace records unresolved tokens, policy levels, utility, crowd size and per-stage timings.", "tokens.py: rehydrate; pipeline.py: Trace"),
            ]
            title, description, source = details[idx]
            st.markdown("**" + title + "**")
            st.write(description)
            st.code(source, language=None)
            if idx == 2:
                st.code("Identity vault: P123 -> Maya Patel; private link F789 -> P123\nContext store:  F789 -> assets, goals, holdings\nOnly the vault stores the link from F789 to Maya.", language=None)
            if idx == 4:
                st.code("Choose highest task utility\nsubject to k(previous disclosures + proposed context) >= 10", language=None)
                st.caption("k is a count under the directory's matching rules. It depends on the chosen reference population and tracked attributes.")
    with data:
        st.subheader("Data used in the project")
        st.write("The project combines public demographic and financial datasets with generated identities and notes. Maya's guided example is a separate, hand-written fictional record.")
        st.table({
            "Dataset": ["Census ACS PUMS 2023", "Federal Reserve SCF 2022", "Financial-Advisory-Clients", "Bitext Wealth Management", "Gretel synthetic PII finance"],
            "Information used": ["Age, state, local area, occupation and income", "Household wealth and financial-asset composition", "Client goals, risk tolerance, horizon, portfolio value and discussion topics", "Wealth-management questions and intent labels", "Synthetic financial documents with labeled PII spans"],
            "Role in the pipeline / evaluation": ["Reference directory for crowd-size and linkage calculations", "Financial-asset donors for the reference directory", "Build experimental client profiles and advisor notes", "Map request intents to tasks and construct repeated-request mixes", "Measure identifier detection recall, precision and leakage"],
        })
        st.subheader("How the experimental client book is built")
        st.markdown("1. Start with ACS demographic records.\n2. Statistically match financial attributes from SCF households using age, income and occupation groups.\n3. Place advisory profiles on matching directory records.\n4. Generate names, identifiers and contact details with Faker, and build notes from profile topics and products.")
        st.caption("This is an experimental combination of sources, not a verified join of the same real people across datasets. Client placement in the directory is part of the evaluation setup.")
        st.subheader("Which data appears where?")
        st.table({
            "View": ["Guided demo", "Hosted interactive app", "Local public-data evaluation", "Fully synthetic mode"],
            "Data": ["Maya Patel: fictional identity and financial values", "Committed ACS sample of 150,000 adults, SCF extract and advisory profiles; a 300-client book", "Processed source files, with sample sizes chosen by the evaluation runner", "Generated population, client records, identities and notes"],
        })
        st.subheader("Example of the guided input")
        st.table({"Field": ["Client", "Age", "Assets", "Objective", "Risk tolerance", "Horizon", "Liquidity need"],
                  "Fictional value": ["Maya Patel", "47", "$3.2 million", "Retirement planning", "Moderate", "15 years", "$80,000 within 12 months"]})
        st.caption("The demo values explain the transformations. Evaluation measurements come from the benchmark datasets above.")
        with st.expander("Dataset sources"):
            st.markdown("- [Census ACS PUMS 2023 files](https://www2.census.gov/programs-surveys/acs/data/pums/2023/1-Year/)\n- [Federal Reserve SCF 2022 extract](https://www.federalreserve.gov/econres/files/scfp2022excel.zip)\n- [Financial-Advisory-Clients](https://huggingface.co/datasets/Finance-Agentic-AI/Financial-Advisory-Clients)\n- [Bitext Wealth Management](https://huggingface.co/datasets/bitext/Bitext-wealth-management-llm-chatbot-training-dataset)\n- [Gretel synthetic PII finance](https://huggingface.co/datasets/gretelai/synthetic_pii_finance_multilingual)")
    with models:
        st.subheader("Tech stack")
        st.table({
            "Component": ["Application", "Interface", "Data processing", "Storage", "Field encryption", "Session tokens", "Privacy policy", "Evaluation tooling"],
            "Technology": ["Python", "Streamlit", "pandas and NumPy", "SQLite", "cryptography: AES-256-GCM", "Python hmac: HMAC-SHA256", "KEngine and ExposureLedger", "scikit-learn and Matplotlib"],
            "Role": ["Coordinates the pipeline and evaluation runners", "Guided walkthrough and interactive comparisons", "Loads datasets and computes matching statistics", "Separates identity and financial context", "Encrypts selected identifier fields in the vault", "Creates session-specific pseudonyms with local restoration mappings", "Selects disclosure levels and tracks cumulative exposure", "Runs inference and strategy-extraction experiments and plots results"],
        })
        st.write("Storage, tokenization, policy selection and restoration run in local Python code. Hosted models serve the roles below.")
        st.subheader("Model roles in the configured Groq evaluation")
        st.table({
            "Role": ["Guided demo answer", "PII detection benchmark", "Advisor answer generation", "Answer-quality judge", "Attribute-inference attacker"],
            "Model / method": ["Scripted example", "openai/gpt-oss-20b via Groq", "openai/gpt-oss-120b via Groq", "Same configured answer model", "Same configured answer model"],
            "Purpose": ["Explain the flow without an API call", "Extract identifier spans from benchmark documents", "Generate briefs from full or reduced context", "Score reduced-context answers against full-context answers", "Guess hidden occupation group, region and age band"],
        })
        st.write("These are the runner defaults. GROQ_DETECT_MODEL and GROQ_LLM_MODEL can override them. The interactive app currently defaults to simulated answers; the Groq runner is separate.")
        st.caption("Benchmark data flow: the hosted detector sees original benchmark text; the full-context baseline and grader also use identifying content. Protected answer generation receives the selected tokenized context.")
        st.write("The answer-quality pipeline uses regex plus the CRM dictionary for its preprocessing. The hosted PII detector is evaluated separately in stage 1.")
    with metrics:
        st.subheader("What the evaluation measures")
        st.caption("Metric definitions and evaluation design. Completed measurements are shown separately in the full app's Evaluation view.")
        st.table({
            "Metric": ["PII recall", "Detection precision", "Documents with identifier leakage", "Crowd size k", "Unique / below-threshold share", "Cumulative k", "Task utility", "LLM judge score", "Attribute inference", "Token restoration", "Strategy extraction", "Latency"],
            "Meaning": [
                "Share of labeled identifier spans covered at least 90% by detections; label need not match.",
                "Share of predicted spans that overlap a labeled identifier.",
                "Share of evaluated documents with at least one missed direct identifier.",
                "Number of directory entries matching the disclosed quasi-identifiers under the engine's matching rules.",
                "Share of evaluated clients with k = 1 or k < 10.",
                "Crowd size after combining information disclosed across requests.",
                "Rule-based task-information score, separate from generated answer quality.",
                "1 to 5 usefulness score relative to the full-context answer; 5 means equally useful.",
                "Accuracy of guesses for hidden occupation group, region and age band.",
                "Restored, repaired, unresolved and silently incorrect token outcomes, depending on the evaluation.",
                "Surrogate equity-allocation error and accuracy of recovered alternatives/collar rules.",
                "Milliseconds spent on detection, re-keying, policy selection, inference and restoration.",
            ],
            "Preferred direction": ["Higher", "Higher", "Lower", "Higher for privacy", "Lower", "Stay above threshold", "Higher", "Higher", "Lower attacker accuracy", "More restored; fewer incorrect", "Higher attacker error; lower recovery", "Lower"],
        })
        st.markdown("**Comparison:** full context, masking only, fixed task policy and adaptive policy.")
        st.write("The launcher evaluates detection on up to 120 documents and 50 client-note records, then evaluates answers for 8 clients across the three core tasks: meeting preparation, concentration checks and retirement income estimates.")
        st.caption("Judge scores use the same model as answer generation, with full-context answers assigned 5 as the reference. They measure relative usefulness, not independently verified financial correctness. Utility and privacy should be read together.")
